    // >>> GENERATED by tools/gen_output_forms_cases.py（勿手改；重跑生成器覆盖本段）
    /// ===== 块 A 差分（期望值由生成器从真源取）=====
    ///
    /// 覆盖：形态清单自检（`registry_verify`）/ 形态识别 + 档位（`detect`，逐件）/ XML 面
    /// （`_check_xml` / `_check_graphml`，逐件）。XML 良构失败的**文本不可比**（CPython 的
    /// ParseError vs 本线），真语料上全部良构，故本条不涉该偏差。
    #[test]
    fn output_forms_registry_matches_truth_source() {
        let root = crate::testutil::repo_root();
        let (issues, stats) = registry_verify(&root);
        assert_eq!(issues, &[] as &[&str]);
        let want: Json = crate::jsonread::convert(
            &serde_json::from_str::<serde_json::Value>(r#"{"by_category": {"ai-domain": 15, "chart": 8, "contract": 8, "diagram": 3, "document": 9, "graph-structure": 10, "interface": 13, "packaging": 5, "quant-domain": 22, "structured-data": 8, "tabular": 9, "timeseries": 6}, "by_status": {"absorbed": 17, "deferred": 11, "planned": 61, "reference": 10, "supported": 11, "unfit": 6}, "by_tier": {"T1": 22, "T2": 55, "T3": 39}, "categories": 12, "forms": 116, "unreachable": 6}"#).unwrap(),
        )
        .unwrap();
        assert!(
            crate::jsonread::json_eq(&stats, &want),
            "registry stats 不一致\n  实得 {}\n  期望 {}",
            stats.dumps(),
            want.dumps()
        );
    }

